import sys

def main():
    data = sys.stdin.read().split()
    n, k = int(data[0]), int(data[1])
    A = sorted((int(x) for x in data[2:2 + n]), reverse=True)
    top = A[:k]
    rest = A[k:]
    s = sum(top)
    if s % 2 == 0:
        print(s)
        return
    odd_top = even_top = None
    for x in reversed(top):
        if x % 2 and odd_top is None:
            odd_top = x
        if x % 2 == 0 and even_top is None:
            even_top = x
    odd_rest = even_rest = None
    for x in rest:
        if x % 2 and odd_rest is None:
            odd_rest = x
        if x % 2 == 0 and even_rest is None:
            even_rest = x
    cands = []
    if odd_top is not None and even_rest is not None:
        cands.append(s - odd_top + even_rest)
    if even_top is not None and odd_rest is not None:
        cands.append(s - even_top + odd_rest)
    print(max(cands) if cands else -1)

main()

